/**
 * #5649 — resolve the MCP caller's API-key **principal id** for content stores
 * (CCR) that are keyed by principal.
 *
 * The CCR store keys blocks by `String(apiKeyInfo.id)` at compression time
 * (`chatCore` → `apiKeyInfo = getApiKeyMetadata(rawKey)`). MCP tool retrieval must
 * resolve the SAME id or the block is not found. On the MCP HTTP transports
 * (SSE / Streamable HTTP) the raw key lives in `httpAuthContext`'s
 * AsyncLocalStorage (set by `withMcpHttpAuthContext`), NOT in the tool handler's
 * `extra.authInfo` (OmniRoute authenticates with API keys, not OAuth client ids —
 * so `extra.authInfo.clientId` is never populated and the caller resolved to
 * "anonymous", producing a cross-principal store-key miss).
 *
 * On stdio transport (`omniroute --mcp`) there is no HTTP context, so we fall
 * back to the OMNIROUTE_API_KEY / ROUTER_API_KEY environment variable.
 *
 * Resolving through the same `getApiKeyMetadata` lookup keeps cross-tenant IDOR
 * isolation intact: a different key → a different id → a miss; no key → undefined
 * → the anonymous (`__anon__`) bucket, which only matches unauthenticated stores.
 */
import { getMcpHttpAuthHeadersForInternalFetch } from "./httpAuthContext.ts";

type ApiKeyLookup = (rawKey: string) => Promise<{ id?: string | number | null } | null>;

/**
 * Load the API-key lookup only after a key is present. Importing the database
 * module eagerly makes every unauthenticated MCP tool import initialize the
 * full SQLite migration stack, even though there is no principal to resolve.
 * That is both unnecessary at runtime and makes parallel test workers contend
 * on a temporary database before the audit test can reach its mock seam.
 */
async function lookupApiKeyMetadata(
  rawKey: string
): Promise<{ id?: string | number | null } | null> {
  const { getApiKeyMetadata } = await import("../../src/lib/db/apiKeys.ts");
  return getApiKeyMetadata(rawKey);
}

/**
 * Pure resolver: given the request auth headers and a key→metadata lookup, return
 * the principal id (as a string) or `undefined`. Separated from the AsyncLocalStorage
 * read so it is unit-testable without a live transport or DB.
 */
export async function resolvePrincipalFromHeaders(
  headers: Record<string, string>,
  lookup: ApiKeyLookup = lookupApiKeyMetadata
): Promise<string | undefined> {
  // Nothing to resolve without an Authorization / x-api-key header.
  if (!headers.Authorization && !headers["x-api-key"]) return undefined;
  const { extractApiKey } = await import("../../src/sse/services/auth.ts");
  const rawKey = extractApiKey({ headers: new Headers(headers) }, { allowUrl: false });
  if (!rawKey) return undefined;
  try {
    const meta = await lookup(rawKey);
    return meta?.id != null && meta.id !== "" ? String(meta.id) : undefined;
  } catch {
    // Fail closed: an unresolved principal can only reach the anonymous bucket.
    return undefined;
  }
}

/**
 * Resolve the current MCP HTTP caller's API-key principal id from the ambient
 * `httpAuthContext`. Returns `undefined` off the HTTP transport (stdio) or when the
 * request carries no API key.
 *
 * Falls back to OMNIROUTE_API_KEY / ROUTER_API_KEY env vars for stdio transport
 * where there is no HTTP context. The env var resolves through the same
 * `getApiKeyMetadata()` lookup that storage (chatCore) uses, so the principal
 * matches. Both storage and retrieval get `{id: "env-key"}` when the env var
 * matches the configured key — consistent and correct.
 */
export async function resolveMcpCallerApiKeyId(): Promise<string | undefined> {
  // 1. Try per-request HTTP auth headers (SSE / Streamable HTTP transport)
  const fromHeaders = await resolvePrincipalFromHeaders(getMcpHttpAuthHeadersForInternalFetch());
  if (fromHeaders !== undefined) return fromHeaders;

  // 2. Fallback: env var (stdio transport, no HTTP context)
  return resolvePrincipalFromEnv();
}

/**
 * Resolve the principal id from the OMNIROUTE_API_KEY (or ROUTER_API_KEY) env var.
 * Used when the MCP server runs on stdio transport and there's no HTTP context.
 * Uses the same getApiKeyMetadata() lookup as storage (chatCore.ts:1336).
 *
 * NOTE: When the key matches the configured env key, getApiKeyMetadata returns
 * `{id: "env-key"}` (not a DB row ID). This is correct — storage on the same
 * process uses the same env var and gets the same `"env-key"` principal, so the
 * store key matches.
 */
async function resolvePrincipalFromEnv(): Promise<string | undefined> {
  const rawKey = process.env.OMNIROUTE_API_KEY || process.env.ROUTER_API_KEY;
  if (!rawKey) return undefined;
  try {
    const meta = await lookupApiKeyMetadata(rawKey);
    return meta?.id != null && meta.id !== "" ? String(meta.id) : undefined;
  } catch {
    return undefined;
  }
}

/**
 * The owner id a tool that stores or reads per-tenant data must act as. The authenticated caller
 * always wins over an id the caller wrote into the tool arguments; otherwise any MCP client could
 * read, change or run another tenant's memories and skills, or the global ones, by naming them.
 *
 * `extra.authInfo.clientId` is the key id the transport resolved with the same extractor the route
 * used to authenticate the request, so it covers every header form the route accepts. The
 * request-header lookup is kept as a second source, and the explicit argument is honoured only when
 * no caller can be resolved at all (a local process with no key, which is already trusted).
 */
export async function resolveMcpToolOwnerId(
  extra: { authInfo?: { clientId?: string } } | undefined,
  explicit?: string
): Promise<string | undefined> {
  const authenticated =
    typeof extra?.authInfo?.clientId === "string" ? extra.authInfo.clientId.trim() : "";
  if (authenticated) return authenticated;
  const caller = await resolveMcpCallerApiKeyId().catch(() => undefined);
  if (caller) return caller;
  const requested = typeof explicit === "string" ? explicit.trim() : "";
  return requested || undefined;
}

import type { SpecificityResult, SpecificityBreakdown, SpecificityLevel } from "./specificityTypes";
import { getSpecificityBreakdown, estimateMessageTokens } from "./specificityRules";

const MAX_SPECIFICITY_SCORE = 100;

export function analyzeSpecificity(
  input: import("./specificityTypes").RuleInput
): SpecificityResult {
  const breakdown = getSpecificityBreakdown(input);
  const score = sumBreakdown(breakdown);
  const inputTokens = estimateMessageTokens(input.messages);
  const rulesTriggered = getTriggeredRules(breakdown);
  const confidence = calculateConfidence(breakdown, input);

  return {
    score: Math.min(MAX_SPECIFICITY_SCORE, score),
    breakdown,
    rulesTriggered,
    inputTokens,
    confidence,
  };
}

function sumBreakdown(breakdown: SpecificityBreakdown): number {
  return (
    breakdown.codeComplexity +
    breakdown.mathComplexity +
    breakdown.reasoningDepth +
    breakdown.contextSize +
    breakdown.toolCalling +
    breakdown.domainSpecificity
  );
}

function getTriggeredRules(breakdown: SpecificityBreakdown): string[] {
  const triggered: string[] = [];
  if (breakdown.codeComplexity > 0) triggered.push("code-complexity");
  if (breakdown.mathComplexity > 0) triggered.push("math-complexity");
  if (breakdown.reasoningDepth > 0) triggered.push("reasoning-depth");
  if (breakdown.contextSize > 0) triggered.push("context-size");
  if (breakdown.toolCalling > 0) triggered.push("tool-calling");
  if (breakdown.domainSpecificity > 0) triggered.push("domain-specificity");
  return triggered;
}

function calculateConfidence(
  breakdown: SpecificityBreakdown,
  input: import("./specificityTypes").RuleInput
): number {
  const nonZero = Object.values(breakdown).filter((v) => v > 0).length;
  const totalCategories = 6;
  const categoryCoverage = nonZero / totalCategories;

  const hasSubstantialInput = input.messages.length >= 2;
  const confidenceBoost = hasSubstantialInput ? 0.1 : 0;

  return Math.min(1, categoryCoverage * 0.8 + confidenceBoost);
}

export function getSpecificityLevel(score: number): SpecificityLevel {
  if (score <= 5) return "trivial";
  if (score <= 20) return "simple";
  if (score <= 40) return "moderate";
  if (score <= 65) return "complex";
  return "expert";
}

export function getRecommendedMinTier(level: SpecificityLevel): string {
  switch (level) {
    case "trivial":
      return "free";
    case "simple":
      return "free";
    case "moderate":
      return "cheap";
    case "complex":
      return "cheap";
    case "expert":
      return "premium";
  }
}

export function isHighSpecificity(result: SpecificityResult): boolean {
  return result.score >= 50;
}

export function isLowSpecificity(result: SpecificityResult): boolean {
  return result.score <= 15;
}

import type { SpecificityBreakdown, RuleInput } from "./specificityTypes";

export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

export function estimateMessageTokens(messages: Array<{ content?: string | unknown }>): number {
  return messages.reduce((sum, msg) => {
    if (typeof msg.content === "string") return sum + estimateTokens(msg.content);
    if (Array.isArray(msg.content)) {
      return (
        sum +
        msg.content.reduce(
          (s: number, part: unknown) =>
            s +
            (typeof (part as { text?: string })?.text === "string"
              ? estimateTokens((part as { text: string }).text)
              : 0),
          0
        )
      );
    }
    return sum;
  }, 0);
}

export function detectCodeComplexity(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const codeFenceMatches = allText.match(/```[\s\S]*?```/g);
  const codeBlockCount = codeFenceMatches ? codeFenceMatches.length : 0;

  const inlineCodeMatches = allText.match(/`[^`]+`/g);
  const inlineCodeCount = inlineCodeMatches ? inlineCodeMatches.length : 0;

  const langIndicators = [
    /function\s+\w+\s*\(/gi,
    /const\s+\w+\s*=/gi,
    /import\s+.*from/gi,
    /class\s+\w+/gi,
    /interface\s+\w+/gi,
    /async\s+function/gi,
    /def\s+\w+\s*\(/gi,
    /SELECT\s+.*FROM/gi,
    /\$\{.*\}/g,
  ];
  const langMatches = langIndicators.reduce((sum, re) => {
    const matches = allText.match(re);
    return sum + (matches ? matches.length : 0);
  }, 0);

  const raw = codeBlockCount * 5 + inlineCodeCount * 0.5 + langMatches * 2;
  return Math.min(25, Math.round(raw));
}

export function detectMathComplexity(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const latexMatches = allText.match(/\$\$[\s\S]*?\$\$|\$[^$]+\$/g);
  const latexCount = latexMatches ? latexMatches.length : 0;

  const mathIndicators = [
    /[+\-*/^]=/g,
    /\b(sin|cos|tan|log|sqrt|sum|prod|int|lim)\b/gi,
    /\b\d+\s*[+\-*/]\s*\d+\s*=/g,
    /∑|∏|∫|√|∞|π/g,
    /\bf'(?:x)?\b/g,
    /\bdx\b/g,
  ];
  const mathMatches = mathIndicators.reduce((sum, re) => {
    const matches = allText.match(re);
    return sum + (matches ? matches.length : 0);
  }, 0);

  const raw = latexCount * 4 + mathMatches * 1.5;
  return Math.min(20, Math.round(raw));
}

export function detectReasoningDepth(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const reasoningIndicators = [
    /\b(first|step\s*\d|secondly|finally|therefore|thus|consequently|because|since)\b/gi,
    /\b(let me think|let's reason|let's analyze|step by step|breaking this down)\b/gi,
    /\b(we need to|we must|we should|the approach is|the solution involves)\b/gi,
    /(?:\d+\.\s+)(?:\w+)/g,
    /\b(if\s+.+\s+then\s+|assuming\s+|suppose\s+|consider\s+that)\b/gi,
  ];

  const reasonMatches = reasoningIndicators.reduce((sum, re) => {
    const matches = allText.match(re);
    return sum + (matches ? matches.length : 0);
  }, 0);

  const messageDepthBonus = Math.min(5, input.messages.length);

  const raw = reasonMatches * 2 + messageDepthBonus;
  return Math.min(20, Math.round(raw));
}

export function detectContextSize(input: RuleInput): number {
  const totalTokens = estimateMessageTokens(input.messages);
  if (totalTokens > 64000) return 15;
  if (totalTokens > 32000) return 12;
  if (totalTokens > 16000) return 9;
  if (totalTokens > 8000) return 6;
  if (totalTokens > 4000) return 4;
  if (totalTokens > 1000) return 2;
  return 0;
}

export function detectToolCalling(input: RuleInput): number {
  if (!input.tools || input.tools.length === 0) return 0;

  const toolCount = input.tools.length;
  if (toolCount > 20) return 10;
  if (toolCount > 10) return 8;
  if (toolCount > 5) return 6;
  if (toolCount > 2) return 4;
  return 2;
}

export function detectDomainSpecificity(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const domainTerms: Record<string, RegExp[]> = {
    medical: [/\bdiagnosis\b/i, /\bsymptoms\b/i, /\btreatment\b/i, /\bpatient\b/i, /\bclinical\b/i],
    legal: [/\bpursuant\b/i, /\bstatute\b/i, /\bliability\b/i, /\bjurisdiction\b/i, /\bhereby\b/i],
    scientific: [/\bhypothesis\b/i, /\bmethodology\b/i, /\bempirical\b/i, /\bsignificant\b/i],
    financial: [/\bportfolio\b/i, /\bdividend\b/i, /\bamortization\b/i, /\barbitrage\b/i],
  };

  let maxDomainScore = 0;
  for (const [, terms] of Object.entries(domainTerms)) {
    const score = terms.reduce((sum, re) => {
      return sum + (re.test(allText) ? 2 : 0);
    }, 0);
    maxDomainScore = Math.max(maxDomainScore, score);
  }

  return Math.min(10, maxDomainScore);
}

export function getSpecificityBreakdown(input: RuleInput): SpecificityBreakdown {
  return {
    codeComplexity: detectCodeComplexity(input),
    mathComplexity: detectMathComplexity(input),
    reasoningDepth: detectReasoningDepth(input),
    contextSize: detectContextSize(input),
    toolCalling: detectToolCalling(input),
    domainSpecificity: detectDomainSpecificity(input),
  };
}

export function detectConversationDepth(input: RuleInput): number {
  const userMessages = input.messages.filter(
    (m) => (m as { role?: string }).role === "user"
  ).length;
  const assistantMessages = input.messages.filter(
    (m) => (m as { role?: string }).role === "assistant"
  ).length;

  const totalTurns = userMessages + assistantMessages;
  if (totalTurns > 30) return 8;
  if (totalTurns > 20) return 6;
  if (totalTurns > 10) return 4;
  if (totalTurns > 5) return 2;
  return 0;
}

export function detectFileReferences(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const filePatterns = [
    /(?:\/[\w.-]+){2,}/g,
    /\b\w+:\d+:\d+\b/g,
    /\b(?:diff|patch|merge)\b/gi,
    /\b(?:README|CHANGELOG|TODO)\b/gi,
    /@@[\s+-]+\d+,\d+\s+@@/g,
  ];

  const matches = filePatterns.reduce((sum, re) => {
    return sum + (allText.match(re)?.length || 0);
  }, 0);

  return Math.min(5, matches * 1);
}

export function detectErrorContext(input: RuleInput): number {
  const allText = input.messages
    .map((m) => (typeof m.content === "string" ? m.content : ""))
    .join("\n");

  const errorPatterns = [
    /\b(?:Error|Exception|TypeError|ReferenceError|SyntaxError)\b/g,
    /\bat\s+[\w.]+\s+\([\w./]+:\d+:\d+\)/g,
    /\b(?:throw|catch|finally)\b/g,
    /\b(?:ERRO|FATAL|WARN)\b/g,
    /\b(?:failed|crashed|unexpected)\b/gi,
    /\bExit code \d+\b/g,
  ];

  const matches = errorPatterns.reduce((sum, re) => {
    return sum + (allText.match(re)?.length || 0);
  }, 0);

  return Math.min(5, matches * 0.5);
}

export function detectEnhancedContextSize(input: RuleInput): number {
  const msgTokens = estimateMessageTokens(input.messages);
  const sysTokens = input.systemPrompt ? estimateTokens(input.systemPrompt) : 0;
  const toolTokens = input.tools
    ? input.tools.reduce(
        (sum, t) =>
          sum +
          estimateTokens(
            JSON.stringify(
              (t as { function?: { description?: string; parameters?: unknown } })?.function || t
            )
          ),
        0
      )
    : 0;

  const total = msgTokens + sysTokens + toolTokens;

  if (total > 100000) return 15;
  if (total > 64000) return 13;
  if (total > 32000) return 10;
  if (total > 16000) return 7;
  if (total > 8000) return 5;
  if (total > 4000) return 3;
  if (total > 1000) return 1;
  return 0;
}

export function getEnhancedSpecificityBreakdown(input: RuleInput): SpecificityBreakdown {
  return {
    codeComplexity: detectCodeComplexity(input),
    mathComplexity: detectMathComplexity(input),
    reasoningDepth: detectReasoningDepth(input),
    contextSize: detectEnhancedContextSize(input),
    toolCalling: detectToolCalling(input),
    domainSpecificity: detectDomainSpecificity(input),
  };
}

/**
 * Query specificity / complexity detection types for Manifest routing integration.
 */

export interface SpecificityResult {
  score: number;
  breakdown: SpecificityBreakdown;
  rulesTriggered: string[];
  inputTokens: number;
  confidence: number;
}

export interface SpecificityBreakdown {
  codeComplexity: number;
  mathComplexity: number;
  reasoningDepth: number;
  contextSize: number;
  toolCalling: number;
  domainSpecificity: number;
}

export interface SpecificityRule {
  name: string;
  category: keyof SpecificityBreakdown;
  weight: number;
  detect(input: RuleInput): RuleMatch | null;
}

export interface RuleInput {
  messages: Array<{ role?: string; content?: string | unknown }>;
  systemPrompt?: string;
  tools?: Array<{
    type?: string;
    function?: { name: string; description?: string; parameters?: unknown };
  }>;
  model?: string;
}

export interface RuleMatch {
  score: number;
  evidence: string;
}

export type SpecificityLevel = "trivial" | "simple" | "moderate" | "complex" | "expert";

import sharp from "sharp";

type Rectangle = {
  height: number;
  value: number;
  width: number;
  x: number;
  y: number;
};

const FIXTURE_WIDTH = 256;
const FIXTURE_HEIGHT = 144;

async function renderJpeg(rectangles: readonly Rectangle[]): Promise<string> {
  const pixels = Buffer.alloc(FIXTURE_WIDTH * FIXTURE_HEIGHT * 3, 255);
  for (const rectangle of rectangles) {
    for (let y = rectangle.y; y < rectangle.y + rectangle.height; y++) {
      for (let x = rectangle.x; x < rectangle.x + rectangle.width; x++) {
        const offset = (y * FIXTURE_WIDTH + x) * 3;
        pixels[offset] = rectangle.value;
        pixels[offset + 1] = rectangle.value;
        pixels[offset + 2] = rectangle.value;
      }
    }
  }
  const jpeg = await sharp(pixels, {
    raw: { channels: 3, height: FIXTURE_HEIGHT, width: FIXTURE_WIDTH },
  })
    .jpeg({ chromaSubsampling: "4:4:4", quality: 100 })
    .toBuffer();
  return `data:image/jpeg;base64,${jpeg.toString("base64")}`;
}

export async function createVideoDedupFixtures(): Promise<{
  smallMotion: readonly [string, string];
  staticFrame: string;
  visibleText: readonly [string, string];
}> {
  const staticFrame = await renderJpeg([{ height: 48, value: 0, width: 48, x: 64, y: 48 }]);
  const movedFrame = await renderJpeg([{ height: 48, value: 0, width: 48, x: 68, y: 48 }]);
  // Rectangular strokes stand in for glyphs without depending on platform fonts.
  const textBefore = [
    { height: 64, value: 0, width: 8, x: 32, y: 32 },
    { height: 64, value: 0, width: 8, x: 48, y: 32 },
    { height: 64, value: 0, width: 8, x: 64, y: 32 },
  ] as const;
  const textAfter = [...textBefore, { height: 64, value: 0, width: 8, x: 80, y: 32 }] as const;
  return {
    smallMotion: [staticFrame, movedFrame],
    staticFrame,
    visibleText: [await renderJpeg(textBefore), await renderJpeg(textAfter)],
  };
}

import assert from "node:assert/strict";
