  const glmOrganizationId =
    (typeof data.glmOrganizationId === "string" && data.glmOrganizationId.trim()) ||
    (typeof data.bigmodelOrganization === "string" && data.bigmodelOrganization.trim()) ||
    (typeof data.glmOrganization === "string" && data.glmOrganization.trim()) ||
    "";
  const glmProjectId =
    (typeof data.glmProjectId === "string" && data.glmProjectId.trim()) ||
    (typeof data.bigmodelProject === "string" && data.bigmodelProject.trim()) ||
    (typeof data.glmProject === "string" && data.glmProject.trim()) ||
    "";
  if (Boolean(glmOrganizationId) !== Boolean(glmProjectId)) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message:
        "providerSpecificData.glmOrganizationId and glmProjectId must both be set for GLM team plan quota",
      path: glmOrganizationId ? ["glmProjectId"] : ["glmOrganizationId"],
    });
  }

  const groupTag = data.tag;
  if (
    groupTag !== undefined &&
    groupTag !== null &&
    (typeof groupTag !== "string" || groupTag.length > 100)
  ) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "providerSpecificData.tag must be a string up to 100 chars",
      path: ["tag"],
    });
  }

  const routingTags = data.tags;
  if (routingTags !== undefined && routingTags !== null) {
    if (!Array.isArray(routingTags) || routingTags.length > 50) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "providerSpecificData.tags must be an array with at most 50 items",
        path: ["tags"],
      });
    } else if (
      routingTags.some(
        (tag) => typeof tag !== "string" || tag.trim().length === 0 || tag.trim().length > 64
      )
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message:
          "providerSpecificData.tags must contain non-empty strings up to 64 characters each",
        path: ["tags"],
      });
    }
  }

  const excludedModels = data.excludedModels ?? data.excluded_models;
  if (excludedModels !== undefined && excludedModels !== null) {
    if (typeof excludedModels === "string") {
      if (excludedModels.length > 5000) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "providerSpecificData.excludedModels string must be up to 5000 chars",
          path: ["excludedModels"],
        });
      }
    } else if (!Array.isArray(excludedModels) || excludedModels.length > 100) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "providerSpecificData.excludedModels must be an array with at most 100 items",
        path: ["excludedModels"],
      });
    } else if (
      excludedModels.some(
        (pattern) =>
          typeof pattern !== "string" ||
          pattern.trim().length === 0 ||
          pattern.trim().length > 200 ||
          pattern.trim() === "**"
      )
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message:
          "providerSpecificData.excludedModels must contain non-empty patterns up to 200 characters",
        path: ["excludedModels"],
      });
    }
  }

  const clientProfile = data.clientProfile;
  if (clientProfile !== undefined && clientProfile !== null) {
    const normalized = typeof clientProfile === "string" ? clientProfile.trim().toLowerCase() : "";
    if (typeof clientProfile !== "string" || !["ide", "cli"].includes(normalized)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "providerSpecificData.clientProfile must be ide or cli",
        path: ["clientProfile"],
      });
    }
  }

  const newApiAggregatorBalance = data.newApiAggregatorBalance;
  if (
    newApiAggregatorBalance !== undefined &&
    newApiAggregatorBalance !== null &&
    typeof newApiAggregatorBalance !== "boolean"
  ) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "providerSpecificData.newApiAggregatorBalance must be a boolean",
      path: ["newApiAggregatorBalance"],
    });
  }

  const quotaPerUnit = data.quotaPerUnit;
  if (quotaPerUnit !== undefined && quotaPerUnit !== null) {
    if (typeof quotaPerUnit !== "number" || !Number.isFinite(quotaPerUnit) || quotaPerUnit <= 0) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "providerSpecificData.quotaPerUnit must be a positive number",
        path: ["quotaPerUnit"],
      });
    }
  }

  // #15753 — self-tracked Xiaomi MiMo monthly budget override (tokens per month).
  validatePositiveNumberField(data.monthlyTokenLimit, "monthlyTokenLimit", ctx);

  // Per-connection operator timeout tier: a slow model must not monopolize an
  // executor slot indefinitely. Bounded to 24h (anti-DoS); below 1ms is
  // meaningless.
  const timeoutMs = data.timeoutMs;
  if (timeoutMs !== undefined && timeoutMs !== null) {
    if (
      typeof timeoutMs !== "number" ||
      !Number.isInteger(timeoutMs) ||
      timeoutMs < 1 ||
      timeoutMs > MAX_PROVIDER_SPECIFIC_TIMEOUT_MS
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `providerSpecificData.timeoutMs must be an integer between 1 and ${MAX_PROVIDER_SPECIFIC_TIMEOUT_MS}`,
        path: ["timeoutMs"],
      });
    }
  }
}

import { classify429 } from "@omniroute/open-sse/services/antigravity429Engine.ts";
import { sanitizeErrorMessage } from "@omniroute/open-sse/utils/error.ts";

import { getProviderCredentialsWithQuotaPreflight } from "./auth";
import { isCredentialDiagnosticSentinel } from "./credentialSentinel";
import { checkAndRefreshToken } from "./tokenRefresh";
import * as log from "../utils/logger";

interface ImageGenerationResult {
  success: boolean;
  status?: number;
  error?: unknown;
  data?: unknown;
  // #8307: opt-in signal a provider handler can set (via
  // saveImageErrorResult's `retryable` option) when a non-401 failure is
  // still account-specific — e.g. a ChatGPT account that can run Codex but
  // lacks access to the requested image model and returns a specific 400.
  // Only honored together with a connectionId, same as the existing 401 path,
  // so providers that never set it keep the original 401-only fallback
  // behavior unchanged.
  retryable?: boolean;
}

interface ImageCredentialRetryOptions {
  provider: string;
  requestedModel: string | null;
  credentials: any;
  execute: (credentials: any) => Promise<ImageGenerationResult>;
  // GHSA-3w2r: the caller key's connection scope. Account fallback must stay
  // inside it exactly like the first selection did. null = unscoped.
  allowedConnections?: string[] | null;
  // Injectable so unit tests can drive multi-account fallback deterministically
  // without a live DB-backed credential store; production always uses the real
  // getProviderCredentialsWithQuotaPreflight-backed selectNextCredentials below.
  selectNextCredentials?: (
    provider: string,
    requestedModel: string | null,
    excludedConnectionIds: Set<string>,
    allowedConnections: string[] | null
  ) => Promise<any>;
}

interface ImageCredentialRetryResult {
  credentials: any;
  result: ImageGenerationResult;
}

function connectionIdOf(credentials: any): string | null {
  const connectionId = credentials?.connectionId;
  return typeof connectionId === "string" && connectionId.trim().length > 0
    ? connectionId.trim()
    : null;
}

function isCredentialSentinel(credentials: any): boolean {
  // Includes the key-scope sentinel (blockedByKeyPolicy): it carries no secret
  // and must never be dispatched.
  return isCredentialDiagnosticSentinel(credentials);
}

/**
 * Image generation is non-idempotent, so account rotation stays deliberately
 * narrower than chat failover. Antigravity's explicit exhausted-quota signal
 * is safe to retry on another account; an ordinary 429 is not evidence that a
 * different account helps and must not cause account rotation.
 */
export function isAntigravityImageQuotaExhausted(
  provider: string,
  result: ImageGenerationResult
): boolean {
  if (provider !== "antigravity" || Number(result.status) !== 429) return false;

  let errorText = "";
  try {
    errorText =
      typeof result.error === "string" ? result.error : JSON.stringify(result.error ?? "");
  } catch {
    return false;
  }

  return classify429(errorText) === "quota_exhausted";
}

async function defaultSelectNextCredentials(
  provider: string,
  requestedModel: string | null,
  excludedConnectionIds: Set<string>,
  allowedConnections: string[] | null
) {
  return getProviderCredentialsWithQuotaPreflight(
    provider,
    null,
    allowedConnections,
    requestedModel,
    {
      excludeConnectionIds: Array.from(excludedConnectionIds),
    }
  );
}

/**
 * Keep image requests on the same credential lifecycle as chat requests.
 *
 * Each connection is attempted at most once. A refresh failure or upstream 401
 * excludes only that connection for the current request; it does not mutate the
 * account into a terminal state because another request may refresh it normally.
 */
export async function executeImageWithCredentialFallback({
  provider,
  requestedModel,
  credentials,
  execute,
  allowedConnections = null,
  selectNextCredentials = defaultSelectNextCredentials,
}: ImageCredentialRetryOptions): Promise<ImageCredentialRetryResult> {
  // Local/no-auth image providers intentionally have no credential row. They
  // still need one direct attempt, but there is no account identity to refresh
  // or rotate after a 401.
  if (!credentials) {
    return { credentials, result: await execute(credentials) };
  }

  const excludedConnectionIds = new Set<string>();
  let currentCredentials = credentials;
  let lastCredentials = credentials;
  let lastResult: ImageGenerationResult | null = null;

  while (currentCredentials && !isCredentialSentinel(currentCredentials)) {
    const connectionId = connectionIdOf(currentCredentials);
    if (connectionId && excludedConnectionIds.has(connectionId)) break;
    if (connectionId) excludedConnectionIds.add(connectionId);

    try {
      currentCredentials = await checkAndRefreshToken(provider, currentCredentials);
    } catch (error) {
      log.warn("IMAGE", "Credential refresh failed; trying another image-provider account", {
        provider,
        connectionId,
        error: sanitizeErrorMessage(error instanceof Error ? error : new Error(String(error))),
      });
      if (!connectionId) throw error;
      currentCredentials = await selectNextCredentials(
        provider,
        requestedModel,
        excludedConnectionIds,
        allowedConnections
      );
      continue;
    }

    lastCredentials = currentCredentials;
    lastResult = await execute(currentCredentials);
    const shouldTryAnotherAccount =
      Number(lastResult.status) === 401 ||
      lastResult.retryable === true ||
      isAntigravityImageQuotaExhausted(provider, lastResult);
    if (lastResult.success || !shouldTryAnotherAccount || !connectionId) {
      return { credentials: lastCredentials, result: lastResult };
    }

    log.warn("IMAGE", "Image provider rejected credentials; trying another account", {
      provider,
      connectionId,
    });
    currentCredentials = await selectNextCredentials(
      provider,
      requestedModel,
      excludedConnectionIds,
      allowedConnections
    );
  }

  return {
    credentials: lastCredentials,
    result: lastResult || {
      success: false,
      status: 401,
      error: "Authentication failed for all eligible image-provider accounts",
    },
  };
}

// Launched by the unit wrapper with an isolated environment before application imports.
import assert from "node:assert/strict";
import test from "node:test";
import { setImmediate as nextTick } from "node:timers/promises";

import type { CodexWreqWebSocket } from "../../../open-sse/executors/codex/appServerClient.ts";

assert.ok(process.env.DATA_DIR);
assert.ok(process.env.OMNIROUTE_PLUGINS_DIR);
globalThis.fetch = async () => {
  throw new Error("Unexpected network access in Codex lifecycle fixture");
};
const { CodexAppServerExecutor } = await import("../../../open-sse/executors/codex-app-server.ts");

type Frame = Record<string, unknown>;
type Scenario = "normal" | "retry" | "fatal" | "close" | "socket-error" | "early-close";
const PRIVATE_ERROR = "token=[REDACTED] at /srv/private/config.ts\nsecret trace";

function fakeAppServer(scenario: Scenario) {
  let closed = false;
  let closes = 0;
  let outputDelivered = false;
  const sent: Frame[] = [];
  const emit = (frame: Frame) => {
    if (!closed) socket.onmessage?.({ data: JSON.stringify(frame) });
  };
  const notify = (method: string, params: Frame) => emit({ jsonrpc: "2.0", method, params });
  const disconnect = () => {
    closed = true;
    socket.onclose?.();
  };
  const complete = () => {
    if (closed) return;
    outputDelivered = true;
    notify("item/agentMessage/delta", { threadId: "thread-test", delta: "LATE-OK" });
    notify("turn/completed", { turn: { status: "completed" } });
  };
  const afterAccepted = () => {
    if (scenario === "close") return disconnect();
    if (scenario === "socket-error") {
      socket.onerror?.({ message: PRIVATE_ERROR });
      disconnect();
      return;
    }
    if (scenario === "retry" || scenario === "fatal") {
      notify("error", {
        threadId: "thread-test",
        turnId: "turn-test",
        willRetry: scenario === "retry",
        error: { message: PRIVATE_ERROR },
      });
    }
    // Output arrives on a later macrotask, after turn/start has been acknowledged.
    setImmediate(complete);
  };
  const socket: CodexWreqWebSocket = {
    onmessage: null,
    onerror: null,
    onclose: null,
    send(data) {
      const frame = JSON.parse(data) as Frame;
      sent.push(frame);
      if (closed || frame.id == null) return;
      queueMicrotask(() => {
        if (frame.method === "thread/start") {
          // The response resolves its promise, but the awaiting executor has not resumed yet.
          emit({ id: frame.id, result: { thread: { id: "thread-test" } } });
          if (scenario === "early-close") disconnect();
        } else if (frame.method === "turn/start") {
          emit({ id: frame.id, result: { turn: { id: "turn-test", status: "inProgress" } } });
          setImmediate(afterAccepted);
        } else {
          emit({ id: frame.id, result: {} });
        }
      });
    },
    close() {
      closes += 1;
      disconnect();
    },
  };
  return {
    socket,
    sent,
    get closes() {
      return closes;
    },
    get outputDelivered() {
      return outputDelivered;
    },
  };
}

async function executeScenario(scenario: Scenario, stream: boolean) {
  const server = fakeAppServer(scenario);
  const controller = new AbortController();
  const executor = new CodexAppServerExecutor({
    websocketFn: async () => server.socket,
    defaultTimeoutMs: 100,
  });
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const responseText = executor
      .execute({
        model: "gpt-6-luna",
        body: { input: "Reply OK" },
        stream,
        signal: controller.signal,
        credentials: {
          providerSpecificData: {
            codexAppServerUrl: "ws://fixture:1456",
            codexAppServerToken: "[REDACTED]",
          },
        },
      })
      .then((result) => result.response.text());
    const text = await Promise.race([
      responseText,
      new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error("Turn did not settle after transport closed")),
          500
        );
      }),
    ]);
    await nextTick();
    return { text, server };
  } finally {
    clearTimeout(timer);
    controller.abort();
  }
}

function assertFailure(text: string, stream: boolean) {
  assert.ok(!text.includes("private-value"));
  assert.ok(!text.includes("/srv/private"));
  assert.ok(!text.includes("secret trace"));
  if (stream) {
    assert.equal((text.match(/event: response\.failed/g) ?? []).length, 1);
    assert.ok(!text.includes("event: response.completed"));
    assert.equal((text.match(/data: \[DONE\]/g) ?? []).length, 1);
  } else {
    assert.equal(JSON.parse(text).status, "failed");
  }
  assert.match(text, /codex_app_server_turn_failed/);
}

for (const stream of [true, false]) {
  const mode = stream ? "SSE" : "JSON";
  for (const scenario of ["normal", "retry"] as const) {
    test(`${mode}: ${scenario} waits for output after the turn ACK`, async () => {
      const { text, server } = await executeScenario(scenario, stream);
      assert.ok(server.outputDelivered, "the socket must remain open until output arrives");
      assert.match(text, /LATE-OK/);
      assert.ok(!text.includes("response.failed"));
      assert.ok(!text.includes("private-value"));
      if (stream) assert.equal((text.match(/event: response\.completed/g) ?? []).length, 1);
      else assert.equal(JSON.parse(text).status, "completed");
      assert.equal(server.closes, 1);
    });
  }
  for (const scenario of ["fatal", "close", "socket-error", "early-close"] as const) {
    test(`${mode}: ${scenario} settles exactly once without success`, async () => {
      const { text, server } = await executeScenario(scenario, stream);
      assertFailure(text, stream);
      assert.equal(server.closes, 1);
      if (scenario === "early-close") {
        assert.ok(
          !server.sent.some((frame) => frame.method === "turn/start"),
          "a disconnected thread must not start a new turn"
        );
      }
    });
  }
}

import assert from "node:assert/strict";
import { setImmediate as nextTurn } from "node:timers/promises";

assert.ok(process.env.DATA_DIR, "probe must receive an isolated DATA_DIR before imports");
assert.equal(typeof global.gc, "function", "probe requires --expose-gc");
const { createStreamController } = await import("../../../open-sse/utils/streamHandler.ts");

type Payload = { bodyString: string; input: { image_url: string }[] };
function capture(
  payload: Payload,
  calls: { disconnect: number; error: number; drain: number },
  handoff: boolean
) {
  const controller = createStreamController({
    allowCompletedToolHandoffGrace: handoff,
    clientDisconnectGracePeriodMs: handoff ? 1000 : 0,
    onDisconnect() {
      assert.ok(payload.bodyString.length > 0);
      calls.disconnect += 1;
    },
    onError() {
      assert.ok(payload.input[0].image_url.length > 0);
      calls.error += 1;
      return true;
    },
  });
  controller.registerCompletedToolHandoffDrain(() => {
    assert.ok(payload.bodyString.length > 0);
    calls.drain += 1;
  });
  return controller;
}

function prepare(mode: string) {
  const payload = {
    bodyString: "p".repeat(4 * 1024 * 1024),
    input: [{ image_url: `data:image/png;base64,${"a".repeat(1024 * 1024)}` }],
  };
  const ref = new WeakRef(payload);
  const calls = { disconnect: 0, error: 0, drain: 0 };
  const controller = capture(payload, calls, mode.startsWith("handoff"));
  if (mode === "complete") controller.handleComplete();
  if (mode === "disconnect") controller.handleDisconnect("fixture_cancel");
  if (mode === "error") controller.handleError(new Error("fixture_upstream_error"));
  if (mode === "abort") controller.abort();
  if (mode.startsWith("handoff")) {
    controller.markCompletedToolHandoffSeen();
    controller.handleDisconnect("completed_tool_handoff");
    if (mode === "handoff-complete") controller.handleComplete();
  }
  return { mode, ref, controller, calls };
}

const probes = [
  "active",
  "complete",
  "disconnect",
  "error",
  "abort",
  "handoff-draining",
  "handoff-complete",
].map(prepare);
// The controllers deliberately remain reachable, as a caller may retain a
// completed Response. Their callbacks no longer need the full request body.
for (let i = 0; i < 12; i += 1) {
  await nextTurn();
  global.gc!();
}
const results = probes.map(({ mode, ref, controller, calls }) => ({
  mode,
  retained: ref.deref() !== undefined,
  calls,
  connected: controller.isConnected(),
  draining: controller.shouldDeferCompletedToolHandoff(),
}));
console.log(`RETENTION_RESULT=${JSON.stringify(results)}`);

/**
 * #5757 guard fixture — NOT a test file (no `.test.` in the name, so the runner
 * skips it). Exercised by `tests/unit/tsx-runtime-transform-5757.test.ts`.
 *
 * It concentrates the modern JS/TS syntax that the published CLI's runtime
 * `tsx/esm` loader (`bin/omniroute.mjs` → `await import("tsx/esm")`) must
 * transform through esbuild at startup: object/array destructuring + rest,
 * object/array spread, class + private fields, optional chaining, nullish
 * coalescing, logical assignment, async/await and top-level await.
 *
 * If a future esbuild (pulled transitively via `tsx`) cannot transform this on a
 * supported Node runtime, running this file fails — which is the whole point.
 */
class Box {
  value = 41; // public class field
  #secret = 1; // private field

  bump(): number {
    this.value += this.#secret;
    return this.value;
  }
}

async function main() {
  const { a, b, ...rest } = { a: 1, b: 2, c: 3, d: 4 }; // object destructuring + rest
  const [first, ...tail] = [10, 20, 30]; // array destructuring + rest
  const merged = { ...rest, first }; // object spread
  const arr = [...tail, first]; // array spread
  const bumped = new Box().bump(); // class + private field
  const maybe: { x?: { y?: number } } = {};
  const opt = maybe?.x?.y ?? 99; // optional chaining + nullish coalescing
  let acc = 0;
  acc ||= bumped; // logical assignment
  const total = await Promise.resolve(a + b + first + opt + acc); // async/await
  return { a, b, rest, first, tail, merged, arr, bumped, opt, total };
}

const result = await main(); // top-level await
console.log("TSX_TRANSFORM_OK " + JSON.stringify(result));

