    assert.equal(runMigrations(db, { isNewDb: true }), 1);
    assert.equal(columns(db).filter((name) => name === "cpa_auth_index").length, 1);
    assert.deepEqual(db.prepare("SELECT version, name FROM _omniroute_migrations").all(), [
