});

/**
 * Cursor Agent image generation — OpenAI `/v1/images/generations` backed by the
 * Cursor Agent CLI's native `generateImage` tool (real diffusion, not SVG).
 *
 * Why CLI (not AgentService/Run): OmniRoute's Cursor chat executor talks to
 * `agent.v1.AgentService/Run` over protobuf and **rejects** built-in tools
 * (shell/write/…). Image generation is a Cursor-native client tool that the
 * `agent` binary executes locally against the seat. Spawning the CLI with a
 * locked prompt + per-request workspace mirrors the proven seat bridge shape
 * and reuses the same `provider_connections` row as chat (`provider: "cursor"`).
 *
 * Auth: `credentials.accessToken` / `apiKey` from the Cursor OAuth (or API-key)
 * connection. Tokens matching `crsr_…` are exported as `CURSOR_API_KEY`; other
 * session JWTs as `CURSOR_AUTH_TOKEN`. The `account::token` composite used by
 * the chat executor is normalized the same way (`split("::")[1]`).
 *
 * Binary: `CURSOR_AGENT_BIN` → `providerSpecificData.agentBin` → PATH / default
 * shim under `~/.local/bin/agent`. Missing binary → HTTP 501 with install hint.
 */

import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdtemp, readFile, readdir, rm } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { sanitizeErrorMessage } from "../../../utils/error.ts";
import { saveImageErrorResult, saveImageSuccessResult } from "../../imageGeneration.ts";
import { IMAGE_PROVIDERS } from "../../../config/imageRegistry.ts";

export const CURSOR_AGENT_IMAGE_FORMAT = "cursor-agent-image";

const DEFAULT_TIMEOUT_MS = 210_000;
const DEFAULT_MAX_CONCURRENT = 2;
const DEFAULT_MODEL = "auto";
const MAX_N = 4;

// Upper bound on a caller-supplied `timeout_ms`. The Cursor seat is shared and
// CURSOR_IMG_MAX_CONCURRENT defaults to only 2 slots, so a huge per-request
// timeout must not hog a slot and starve every other caller.
const MAX_TIMEOUT_MS = 300_000;

// Models the Agent CLI `--model` argv may receive — kept in sync with the
// registry entry (auto | composer-2 | composer-2.5). The request `model` is
// untrusted input forwarded straight into a spawned CLI, so we mirror the
// auggie executor: anything outside this set (unknown model, or a flag-shaped
// value like "--foo" / "-x") is clamped to DEFAULT_MODEL and never reaches argv.
const CURSOR_IMAGE_MODEL_ALLOWLIST: ReadonlySet<string> = new Set(
  (IMAGE_PROVIDERS.cursor?.models ?? []).map((m) => m.id)
);

/** Clamp a model candidate to the allowlist; unknown/flag-shaped → "auto". */
export function resolveCursorImageModel(candidate: unknown): string {
  const requested = typeof candidate === "string" ? candidate.trim() : "";
  return CURSOR_IMAGE_MODEL_ALLOWLIST.has(requested) ? requested : DEFAULT_MODEL;
}

const PNG_MAGIC = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const JPEG_MAGIC = Buffer.from([0xff, 0xd8, 0xff]);

/**
 * Localities allowed to trigger the `agent` binary spawn below (Hard Rules
 * #15 + #17). `/v1/images/generations` is a normal remote-reachable inference
 * route shared by ~40 image providers that only proxy HTTP — the ONLY branch
 * here that spawns a child process is this one, so the whole route cannot be
 * classified in `LOCAL_ONLY_API_PREFIXES` (routeGuard.ts) without blocking
 * every other, non-spawning image provider for remote callers. Instead this
 * handler enforces its OWN loopback/LAN gate using the trusted locality
 * verdict the authz pipeline already stamps on every request
 * (`AUTHZ_HEADER_PEER_LOCALITY`, src/server/authz/headers.ts, computed from
 * the real TCP peer IP — never the spoofable Host header). Mirrors the
 * loopback-or-private-LAN policy `managementPolicy` applies to every other
 * LOCAL_ONLY route (src/server/authz/policies/management.ts).
 */
const SPAWN_ALLOWED_LOCALITIES = new Set(["loopback", "lan"]);

/** Locked instruction — ingress callers can only trigger image gen, never a shell. */
export function buildCursorAgentImagePrompt(userPrompt: string, outPath: string, size?: unknown): string {
  const sizeHint =
    typeof size === "string" && size.trim() ? ` Target size/aspect: ${size.trim()}.` : "";
  return [
    "You have a native image-generation tool. Use it to generate ONE image.",
    "Do NOT write code, do NOT hand-author SVG, do NOT install packages — use your built-in image generation.",
    `Image to generate: ${userPrompt}.${sizeHint}`,
    `Save the resulting image to exactly this path: ${outPath}.`,
    "When the file exists at that exact path, reply with only the word DONE.",
  ].join(" ");
}

/** Strip OmniRoute `account::token` composites the same way CursorExecutor does. */
export function normalizeCursorSeatToken(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return trimmed;
  return trimmed.includes("::") ? trimmed.split("::").slice(1).join("::").trim() || trimmed : trimmed;
}

/**
 * Map a Cursor connection token into the env vars the Agent CLI reads.
 * Prefer API keys (`crsr_…`) as `CURSOR_API_KEY`; otherwise session JWT → `CURSOR_AUTH_TOKEN`.
 */
export function buildCursorAgentAuthEnv(token: string): Record<string, string> {
  const clean = normalizeCursorSeatToken(token);
  if (clean.startsWith("crsr_")) {
    return { CURSOR_API_KEY: clean };
  }
  return { CURSOR_AUTH_TOKEN: clean };
}

export function resolveCursorAgentBin(override?: string | null): string | null {
  // Explicit connection override wins even when the path is missing — the handler
  // returns 501 so operators see a clear misconfiguration instead of a silent fallback.
  if (typeof override === "string" && override.trim()) {
    return override.trim();
  }
  const envBin = process.env.CURSOR_AGENT_BIN?.trim();
  if (envBin) return envBin;

  const defaultShim = join(homedir(), ".local", "bin", "agent");
  if (existsSync(defaultShim)) return defaultShim;

  // Last resort: bare `agent` on PATH (spawn fails with ENOENT → 501).
  return "agent";
}

export function isRasterImageBuffer(buf: Buffer): boolean {
  if (buf.length >= 8 && buf.subarray(0, 8).equals(PNG_MAGIC)) return true;
  if (buf.length >= 3 && buf.subarray(0, 3).equals(JPEG_MAGIC)) return true;
  return false;
}

export async function findCursorAgentImageOutput(
  workspace: string,
  preferredPath: string
): Promise<string | null> {
  if (existsSync(preferredPath)) return preferredPath;
  try {
    const entries = await readdir(workspace);
    const match = entries.find((name) => /\.(png|jpe?g|webp)$/i.test(name));
    return match ? join(workspace, match) : null;
  } catch {
    return null;
  }
}

function normalizePositiveInt(value: unknown, fallback: number, max?: number): number {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return fallback;
  const i = Math.floor(n);
  return typeof max === "number" ? Math.min(i, max) : i;
}

/**
 * Effective per-image wall clock: a caller-supplied `timeout_ms` clamped to
 * MAX_TIMEOUT_MS. When the request omits it, fall back to the operator default
 * (CURSOR_IMG_TIMEOUT_MS) / DEFAULT_TIMEOUT_MS uncapped — operator config is
 * trusted; only the untrusted request value is clamped.
 */
export function resolveCursorImageTimeoutMs(rawTimeout: unknown): number {
  return normalizePositiveInt(
    rawTimeout,
    normalizePositiveInt(process.env.CURSOR_IMG_TIMEOUT_MS, DEFAULT_TIMEOUT_MS),
    MAX_TIMEOUT_MS
  );
}

type CursorAgentImageCredentials = {
  apiKey?: string;
  accessToken?: string;
  providerSpecificData?: Record<string, unknown> | null;
};

function extractSeatToken(credentials: CursorAgentImageCredentials): string {
  const raw = credentials?.accessToken || credentials?.apiKey || "";
  return typeof raw === "string" ? raw.trim() : "";
}

function extractAgentBinOverride(credentials: CursorAgentImageCredentials): string | null {
  const psd = credentials?.providerSpecificData;
  if (!psd || typeof psd !== "object" || Array.isArray(psd)) return null;
  const bin = psd.agentBin;
  return typeof bin === "string" && bin.trim() ? bin.trim() : null;
}

function extractAgentModel(credentials: CursorAgentImageCredentials, requestModel: string): string {
  const psd = credentials?.providerSpecificData;
  if (psd && typeof psd === "object" && !Array.isArray(psd)) {
    const fromPsd = psd.imageModel;
    if (typeof fromPsd === "string" && fromPsd.trim()) return fromPsd.trim();
  }
  if (process.env.CURSOR_IMG_MODEL?.trim()) return process.env.CURSOR_IMG_MODEL.trim();
  // The request's `model=cursor/<…>` field is untrusted and flows into the CLI
  // `--model` argv — clamp it to the registry allowlist (unknown/flag-shaped →
  // "auto"). The operator overrides above (connection psd / CURSOR_IMG_MODEL)
  // are trusted deployment config and pass through unchanged.
  return resolveCursorImageModel(
    requestModel && requestModel !== "cursor" ? requestModel : DEFAULT_MODEL
  );
}

// ─── process-wide concurrency gate (one shared Cursor seat) ─────────────────

type Waiter = () => void;
let activeGenerations = 0;
const waitQueue: Waiter[] = [];

export function __resetCursorAgentImageConcurrencyForTests(): void {
  activeGenerations = 0;
  waitQueue.length = 0;
}

function maxConcurrent(): number {
  return normalizePositiveInt(process.env.CURSOR_IMG_MAX_CONCURRENT, DEFAULT_MAX_CONCURRENT);
}

async function acquireSlot(): Promise<void> {
  if (activeGenerations < maxConcurrent()) {
    activeGenerations += 1;
    return;
  }
  await new Promise<void>((resolve) => {
    waitQueue.push(() => {
      activeGenerations += 1;
      resolve();
    });
  });
}

function releaseSlot(): void {
  activeGenerations = Math.max(0, activeGenerations - 1);
  const next = waitQueue.shift();
  if (next) next();
}

export type RunCursorAgentImageOptions = {
  agentBin: string;
  workspace: string;
  prompt: string;
  model: string;
  authEnv: Record<string, string>;
  timeoutMs: number;
  spawnImpl?: typeof spawn;
};

/** Spawn `agent -p --force …` and resolve when it exits 0 (or reject on timeout/error). */
export function runCursorAgentImageProcess(opts: RunCursorAgentImageOptions): Promise<{
  stdout: string;
  stderr: string;
}> {
  const spawnImpl = opts.spawnImpl ?? spawn;
  const args = [
    "-p",
    "--force",
    "--model",
    opts.model,
    "--workspace",
    opts.workspace,
    "--output-format",
    "text",
    opts.prompt,
  ];

  return new Promise((resolve, reject) => {
    const child = spawnImpl(opts.agentBin, args, {
      cwd: opts.workspace,
      env: {
        ...process.env,
        ...opts.authEnv,
        HOME: process.env.HOME || homedir(),
      },
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      reject(new Error(`Cursor Agent image generation timed out after ${opts.timeoutMs}ms`));
    }, opts.timeoutMs);

    child.stdout?.on("data", (chunk: Buffer | string) => {
      stdout += String(chunk);
    });
    child.stderr?.on("data", (chunk: Buffer | string) => {
      stderr += String(chunk);
    });
    child.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code === 0) {
        resolve({ stdout, stderr });
        return;
      }
      reject(
        new Error(
          `Cursor Agent exited ${code}: ${(stderr || stdout).trim().slice(0, 400) || "no output"}`
        )
      );
    });
  });
}

async function generateOneImage(params: {
  userPrompt: string;
  size: unknown;
  agentBin: string;
  model: string;
  authEnv: Record<string, string>;
  timeoutMs: number;
  spawnImpl?: typeof spawn;
}): Promise<Buffer> {
  const workspace = await mkdtemp(join(tmpdir(), "omni-cursor-img-"));
  const outPath = join(workspace, "out.png");
  const prompt = buildCursorAgentImagePrompt(params.userPrompt, outPath, params.size);

  try {
    await runCursorAgentImageProcess({
      agentBin: params.agentBin,
      workspace,
      prompt,
      model: params.model,
      authEnv: params.authEnv,
      timeoutMs: params.timeoutMs,
      spawnImpl: params.spawnImpl,
    });

    const found = await findCursorAgentImageOutput(workspace, outPath);
    if (!found) {
      throw new Error("Cursor Agent produced no image file in the workspace");
    }
    const buf = await readFile(found);
    if (!isRasterImageBuffer(buf)) {
      throw new Error("Cursor Agent output is not a PNG/JPEG raster");
    }
    return buf;
  } finally {
    await rm(workspace, { recursive: true, force: true }).catch(() => {});
  }
}

export async function handleCursorAgentImageGeneration({
  model,
  provider,
  providerConfig: _providerConfig,
  body,
  credentials,
  log,
  spawnImpl,
  peerLocality,
}: {
  model: string;
  provider: string;
  providerConfig: { baseUrl?: string };
  body: {
    prompt?: unknown;
    size?: unknown;
    n?: unknown;
    timeout_ms?: unknown;
  };
  credentials: CursorAgentImageCredentials;
  log?: { info?: (...args: unknown[]) => void; error?: (...args: unknown[]) => void };
  /** Test seam — defaults to node:child_process.spawn */
  spawnImpl?: typeof spawn;
  /**
   * Trusted locality verdict ("loopback" | "lan" | "remote") forwarded by the
   * route layer from `AUTHZ_HEADER_PEER_LOCALITY` (stamped by the authz
   * pipeline from the real TCP peer, never the spoofable Host header). Absent
   * or unrecognized → fail closed (treated as "remote").
   */
  peerLocality?: string | null;
}) {
  const startTime = Date.now();

  // Hard Rules #15 + #17: reject before doing ANY other work — credential
  // lookup, prompt validation, and the `agent` binary spawn itself must never
  // run for a non-loopback/non-LAN caller. A leaked API key tunneled from the
  // public internet must not be able to trigger a child-process spawn on the
  // OmniRoute host.
  if (!peerLocality || !SPAWN_ALLOWED_LOCALITIES.has(peerLocality)) {
    return saveImageErrorResult({
      provider,
      model,
      status: 403,
      startTime,
      error:
        "Cursor Agent image generation spawns a local process and is only available from localhost or the private LAN OmniRoute runs on.",
    });
  }

  const prompt = typeof body.prompt === "string" ? body.prompt.trim() : "";
  if (!prompt) {
    return saveImageErrorResult({
      provider,
      model,
      status: 400,
      startTime,
      error: "Prompt is required for Cursor Agent image generation",
    });
  }

  const token = [REDACTED];
  if (!token) {
    return saveImageErrorResult({
      provider,
      model,
      status: 401,
      startTime,
      error: "Cursor credentials missing accessToken — reconnect the Cursor provider",
    });
  }

  const agentBin = resolveCursorAgentBin(extractAgentBinOverride(credentials));
  if (!agentBin || (agentBin !== "agent" && !existsSync(agentBin))) {
    // Bare "agent" may still resolve via PATH; only hard-fail when an explicit path is missing.
    if (agentBin !== "agent") {
      return saveImageErrorResult({
        provider,
        model,
        status: 501,
        startTime,
        error:
          "Cursor Agent CLI not found. Install the Cursor `agent` binary and set CURSOR_AGENT_BIN, or set providerSpecificData.agentBin on the Cursor connection.",
      });
    }
  }

  const timeoutMs = resolveCursorImageTimeoutMs(body.timeout_ms);
  const count = normalizePositiveInt(body.n, 1, MAX_N);
  const agentModel = extractAgentModel(credentials, model);
  const authEnv = buildCursorAgentAuthEnv(token);

  if (log?.info) {
    log.info(
      "IMAGE",
      `${provider}/${model} (cursor-agent-image) | n=${count} model=${agentModel} bin=${agentBin}`
    );
  }

  const images: Array<{ b64_json: string; revised_prompt: string }> = [];

  try {
    for (let i = 0; i < count; i++) {
      await acquireSlot();
      try {
        const buf = await generateOneImage({
          userPrompt: prompt,
          size: body.size,
          agentBin: agentBin || "agent",
          model: agentModel,
          authEnv,
          timeoutMs,
          spawnImpl,
        });
        images.push({ b64_json: buf.toString("base64"), revised_prompt: prompt });
      } finally {
        releaseSlot();
      }
    }

    return saveImageSuccessResult({
      provider,
      model,
      startTime,
      images,
    });
  } catch (err) {
    const errorText = sanitizeErrorMessage(err instanceof Error ? err.message : String(err));
    if (log?.error) {
      log.error("IMAGE", `${provider} cursor-agent-image error: ${errorText}`);
    }
    // ENOENT from spawn → treat as missing CLI
    const status =
      err && typeof err === "object" && "code" in err && (err as { code?: string }).code === "ENOENT"
        ? 501
        : 502;
    return saveImageErrorResult({
      provider,
      model,
      status,
      startTime,
      error:
        status === 501
          ? "Cursor Agent CLI not found on PATH. Set CURSOR_AGENT_BIN to the `agent` binary."
          : errorText,
    });
  }
}

// UC (uncensored.com) image-generation handler.
// Family: uc-image | Provider: uc
//
// UC exposes image generation on TWO surfaces, and this handler serves both,
// picking by which credential is present:
//
//   (A) PERSONA WEB path (un-metered, Clerk-authenticated). No API key: the
//       durable Clerk `__client` cookie lives in the connection's
//       providerSpecificData, from which we mint a short-lived `__session` JWT
//       (mintUcSessionToken) and call:
//         POST https://internal.chatuncensored.ai/v2/image-gen
//           Authorization: Bearer <jwt>, Origin/Referer https://uncensored.com
//           body {prompt, mode:"dev", model_version, m_n_user, moderationMode,
//                 imageHeight, imageWidth, country, aspect_ratio, vdiscount}
//       The response is IMMEDIATE and carries a PRE-DETERMINED result URL:
//         {status:"pending", url:"https://gen.moveinwater.com/img_{uid}_{uuid}.png",
//          request_id}
//       We then POLL that url with GET until HTTP 200 (~4s typical), returning
//       the final url as an OpenAI images response.
//
//   (B) uc-direct REST path (metered, OpenAI-compatible). A `uai_sk_live_...`
//       X-api-key credential is present, so we call the official REST endpoint:
//         POST https://api.uncensored.com/api/v1/images/generations
//           X-api-key: <key>
//           body {model, prompt, n, size}
//       The response is already OpenAI-shaped ({created, data:[{url}|{b64_json}]}).
//
// Residential egress / TLS (if any) is applied transparently at the infra layer;
// nothing egress-specific lives here. The handler is pure and testable: fetch and
// sleep are injectable so unit tests drive the pending→poll→200 sequence with no
// live network.

import { resolveUcCredential } from "../../../executors/uc/credentials.ts";
import { mintUcSessionToken } from "../../../executors/uc/clerkAuth.ts";
import { UC_ORIGIN } from "../../../executors/uc/constants.ts";
import { sanitizeErrorMessage } from "../../../utils/error.ts";
import { saveImageErrorResult, saveImageSuccessResult } from "../../imageGeneration.ts";

/** Persona web image-gen endpoint (immediate response + result-URL polling). */
export const UC_PERSONA_IMAGE_URL = "https://internal.chatuncensored.ai/v2/image-gen";
/** uc-direct metered REST endpoint (OpenAI-compatible). */
export const UC_DIRECT_IMAGE_URL = "https://api.uncensored.com/api/v1/images/generations";

const UC_IMAGE_N_MAX = 4;
const UC_POLL_TIMEOUT_MS_DEFAULT = 60_000;
const UC_POLL_INTERVAL_MS_DEFAULT = 2_000;

/** Aspect ratios UC's web picker accepts, mapped to imageWidth/imageHeight strings. */
const UC_ASPECT_SIZES: Record<string, { imageWidth: string; imageHeight: string }> = {
  "1:1": { imageWidth: "1024", imageHeight: "1024" },
  "16:9": { imageWidth: "1024", imageHeight: "576" },
  "9:16": { imageWidth: "576", imageHeight: "1024" },
  "4:3": { imageWidth: "1024", imageHeight: "768" },
  "3:4": { imageWidth: "768", imageHeight: "1024" },
};

const UC_DEFAULT_ASPECT = "1:1";

/**
 * Strip a routing prefix (`uc/` or `uc-direct/`) and return the canonical UC
 * image model id (the web picker's `model_version` shortname / the REST `model`).
 */
export function resolveUcImageModel(model: unknown): string {
  let m = typeof model === "string" ? model.trim() : "";
  if (m.startsWith("uc-direct/")) m = m.slice("uc-direct/".length);
  else if (m.startsWith("uc/")) m = m.slice("uc/".length);
  return m;
}

/**
 * Resolve an aspect ratio to the {aspect_ratio, imageWidth, imageHeight} the UC
 * persona web body expects (width/height are STRINGS). Accepts either an explicit
 * aspect ratio (`"16:9"`) or an OpenAI-style `"WxH"` size, which is snapped to the
 * nearest supported bucket. Unknown/absent input defaults to 1:1.
 */
export function ucAspectToSize(aspectOrSize: unknown): {
  aspect_ratio: string;
  imageWidth: string;
  imageHeight: string;
} {
  const raw = typeof aspectOrSize === "string" ? aspectOrSize.trim() : "";

  // Explicit aspect ratio (e.g. "16:9").
  if (raw && UC_ASPECT_SIZES[raw]) {
    return { aspect_ratio: raw, ...UC_ASPECT_SIZES[raw] };
  }

  // OpenAI-style "WxH" -> nearest aspect bucket by ratio.
  if (raw.includes("x")) {
    const [wRaw, hRaw] = raw.split("x");
    const w = Number(wRaw);
    const h = Number(hRaw);
    if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {
      const target = w / h;
      let best = UC_DEFAULT_ASPECT;
      let bestDelta = Infinity;
      for (const [aspect, dims] of Object.entries(UC_ASPECT_SIZES)) {
        const r = Number(dims.imageWidth) / Number(dims.imageHeight);
        const delta = Math.abs(r - target);
        if (delta < bestDelta) {
          bestDelta = delta;
          best = aspect;
        }
      }
      return { aspect_ratio: best, ...UC_ASPECT_SIZES[best] };
    }
  }

  return { aspect_ratio: UC_DEFAULT_ASPECT, ...UC_ASPECT_SIZES[UC_DEFAULT_ASPECT] };
}

/** Extract OpenAI image data[] items from a uc-direct REST response. */
export function extractUcDirectImages(json: unknown): Array<{ url?: string; b64_json?: string }> {
  const data =
    json && typeof json === "object" && Array.isArray((json as Record<string, unknown>).data)
      ? ((json as Record<string, unknown>).data as unknown[])
      : [];
  const out: Array<{ url?: string; b64_json?: string }> = [];
  for (const it of data) {
    if (it && typeof it === "object") {
      const rec = it as Record<string, unknown>;
      if (typeof rec.url === "string" && rec.url) out.push({ url: rec.url });
      else if (typeof rec.b64_json === "string" && rec.b64_json)
        out.push({ b64_json: rec.b64_json });
    }
  }
  return out;
}

function normalizePositiveNumber(value: unknown, fallback: number): number {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

type SleepImpl = (ms: number) => Promise<void>;
const realSleep: SleepImpl = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

interface UcImageBody {
  prompt?: unknown;
  size?: unknown;
  aspect_ratio?: unknown;
  n?: unknown;
  timeout_ms?: unknown;
  poll_interval_ms?: unknown;
}

interface UcImageCredentials {
  apiKey?: string;
  accessToken?: string;
  providerSpecificData?: Record<string, unknown> | null;
}

interface UcImageHandlerArgs {
  model: string;
  provider: string;
  body: UcImageBody;
  credentials: UcImageCredentials;
  log?: { info?: (...args: unknown[]) => void; error?: (...args: unknown[]) => void };
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
  sleepImpl?: SleepImpl;
}

/** True when the credential is a uc-direct metered API key (`uai_sk_live_...`). */
function isUcDirectCredential(credentials: UcImageCredentials): boolean {
  const key = typeof credentials?.apiKey === "string" ? credentials.apiKey.trim() : "";
  return key.startsWith("uai_");
}

/**
 * PERSONA WEB path (surface A): mint a Clerk JWT, POST the image-gen request,
 * then poll the pre-determined result URL until it returns 200.
 */
async function handleUcPersonaImage(
  args: Required<Pick<UcImageHandlerArgs, "model" | "provider" | "body" | "credentials">> &
    Pick<UcImageHandlerArgs, "log" | "signal"> & {
      fetchImpl: typeof fetch;
      sleepImpl: SleepImpl;
      startTime: number;
      prompt: string;
    }
) {
  const {
    model,
    provider,
    body,
    credentials,
    log,
    signal,
    fetchImpl,
    sleepImpl,
    startTime,
    prompt,
  } = args;

  const cred = resolveUcCredential(credentials?.providerSpecificData);
  if (!cred) {
    return saveImageErrorResult({
      provider,
      model,
      status: 401,
      startTime,
      error: "UC persona credentials missing (need clientCookie + sid + uid)",
      retryable: true,
    });
  }

  const mint = await mintUcSessionToken({
    sid: cred.sid,
    cookies: cred.cookies,
    fetchImpl,
    signal,
  });
  if (!mint.ok || !mint.token) {
    return saveImageErrorResult({
      provider,
      model,
      status: mint.status === 0 ? 502 : mint.status,
      startTime,
      error: sanitizeErrorMessage(mint.error || "UC Clerk token mint failed"),
      // 401/403 = durable login lapsed or revoked: rotate to the next account.
      retryable: mint.status === 401 || mint.status === 403,
    });
  }

  const modelVersion = resolveUcImageModel(model);
  const { aspect_ratio, imageWidth, imageHeight } = ucAspectToSize(body.aspect_ratio ?? body.size);
  const requestBody = {
    prompt,
    mode: "dev",
    model_version: modelVersion,
    m_n_user: true,
    moderationMode: "SUPER_LIGHT",
    imageHeight,
    imageWidth,
    country: "US",
    aspect_ratio,
    vdiscount: false,
  };
  const headers: Record<string, string> = {
    Authorization: `Bearer ${mint.token.jwt}`,
    Origin: UC_ORIGIN,
    Referer: UC_ORIGIN + "/",
    "Content-Type": "application/json",
  };

  let resp: Response;
  try {
    resp = await fetchImpl(UC_PERSONA_IMAGE_URL, {
      method: "POST",
      headers,
      body: JSON.stringify(requestBody),
      signal,
    });
  } catch (err) {
    const errorText = sanitizeErrorMessage(err instanceof Error ? err.message : String(err));
    log?.error?.("IMAGE", `${provider} uc-image (persona) transport error: ${errorText}`);
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: errorText,
      requestBody,
    });
  }

  if (!resp.ok) {
    const detail = (await resp.text().catch(() => "")).slice(0, 500);
    log?.error?.("IMAGE", `${provider} uc-image (persona) error ${resp.status}: ${detail}`);
    return saveImageErrorResult({
      provider,
      model,
      status: resp.status,
      startTime,
      error: detail || `UC persona image generation failed (HTTP ${resp.status})`,
      requestBody,
      retryable: resp.status === 401 || resp.status === 403,
    });
  }

  let json: unknown;
  try {
    json = await resp.json();
  } catch {
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: "UC persona returned a non-JSON image response",
      requestBody,
    });
  }

  const resultUrl =
    json && typeof json === "object" && typeof (json as Record<string, unknown>).url === "string"
      ? ((json as Record<string, unknown>).url as string)
      : "";
  if (!resultUrl) {
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: "UC persona image response carried no result url",
      requestBody,
    });
  }

  const timeoutMs = normalizePositiveNumber(
    body.timeout_ms,
    normalizePositiveNumber(process.env.UC_IMAGE_POLL_TIMEOUT_MS, UC_POLL_TIMEOUT_MS_DEFAULT)
  );
  const pollIntervalMs = normalizePositiveNumber(
    body.poll_interval_ms,
    normalizePositiveNumber(process.env.UC_IMAGE_POLL_INTERVAL_MS, UC_POLL_INTERVAL_MS_DEFAULT)
  );

  const poll = await pollUcResultUrl(
    resultUrl,
    timeoutMs,
    pollIntervalMs,
    fetchImpl,
    sleepImpl,
    signal,
    log
  );
  if (poll.state === "failed") {
    log?.error?.("IMAGE", `${provider} uc-image (persona) poll ${poll.status}: ${poll.error}`);
    return saveImageErrorResult({
      provider,
      model,
      status: poll.status,
      startTime,
      error: poll.error,
      requestBody,
    });
  }

  return saveImageSuccessResult({
    provider,
    model,
    startTime,
    requestBody,
    responseBody: { images_count: 1 },
    images: [{ url: resultUrl }],
  });
}

type UcPollOutcome = { state: "ready" } | { state: "failed"; status: number; error: string };

/** Poll the pre-determined result URL with GET until HTTP 200, or time out. */
async function pollUcResultUrl(
  url: string,
  timeoutMs: number,
  pollIntervalMs: number,
  fetchImpl: typeof fetch,
  sleepImpl: SleepImpl,
  signal: AbortSignal | undefined,
  log?: { info?: (...args: unknown[]) => void }
): Promise<UcPollOutcome> {
  const deadline = Date.now() + timeoutMs;
  let attempt = 0;
  // Poll at least once even when timeoutMs is 0.
  do {
    attempt += 1;
    let resp: Response;
    try {
      resp = await fetchImpl(url, { method: "GET", signal });
    } catch (err) {
      return {
        state: "failed",
        status: 502,
        error: sanitizeErrorMessage(err instanceof Error ? err.message : String(err)),
      };
    }
    if (resp.ok) return { state: "ready" };
    // 403/404 = not ready yet; anything else is a hard failure.
    if (resp.status !== 403 && resp.status !== 404) {
      return {
        state: "failed",
        status: resp.status,
        error: `UC result URL returned HTTP ${resp.status}`,
      };
    }
    log?.info?.("IMAGE", `uc-image result pending, poll #${attempt} in ${pollIntervalMs}ms`);
    if (Date.now() + pollIntervalMs >= deadline) break;
    await sleepImpl(pollIntervalMs);
  } while (Date.now() < deadline);

  return {
    state: "failed",
    status: 504,
    error: "UC image generation timed out waiting for a result",
  };
}

/**
 * uc-direct REST path (surface B): OpenAI-compatible metered endpoint keyed by
 * `X-api-key`. The response is already OpenAI-shaped.
 */
async function handleUcDirectImage(
  args: Required<Pick<UcImageHandlerArgs, "model" | "provider" | "body" | "credentials">> &
    Pick<UcImageHandlerArgs, "log" | "signal"> & {
      fetchImpl: typeof fetch;
      startTime: number;
      prompt: string;
    }
) {
  const { model, provider, body, credentials, log, signal, fetchImpl, startTime, prompt } = args;

  const apiKey = typeof credentials.apiKey === "string" ? credentials.apiKey.trim() : "";
  const canonicalModel = resolveUcImageModel(model);
  const nRaw = Number(body.n);
  const n = Number.isFinite(nRaw) && nRaw >= 1 ? Math.min(Math.floor(nRaw), UC_IMAGE_N_MAX) : 1;
  const requestBody: Record<string, unknown> = {
    model: canonicalModel,
    prompt,
    n,
  };
  if (typeof body.size === "string" && body.size.trim()) requestBody.size = body.size.trim();

  const headers: Record<string, string> = {
    "X-api-key": apiKey,
    "Content-Type": "application/json",
  };

  let resp: Response;
  try {
    resp = await fetchImpl(UC_DIRECT_IMAGE_URL, {
      method: "POST",
      headers,
      body: JSON.stringify(requestBody),
      signal,
    });
  } catch (err) {
    const errorText = sanitizeErrorMessage(err instanceof Error ? err.message : String(err));
    log?.error?.("IMAGE", `${provider} uc-image (direct) transport error: ${errorText}`);
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: errorText,
      requestBody,
    });
  }

  if (!resp.ok) {
    const detail = (await resp.text().catch(() => "")).slice(0, 500);
    log?.error?.("IMAGE", `${provider} uc-image (direct) error ${resp.status}: ${detail}`);
    return saveImageErrorResult({
      provider,
      model,
      status: resp.status,
      startTime,
      error: detail || `UC direct image generation failed (HTTP ${resp.status})`,
      requestBody,
      // 429 = rate limit (retry another account/later). 402 funds / 403 moderation
      // are non-retryable per the REST error contract.
      retryable: resp.status === 429 || undefined,
    });
  }

  let json: unknown;
  try {
    json = await resp.json();
  } catch {
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: "UC direct returned a non-JSON image response",
      requestBody,
    });
  }

  const images = extractUcDirectImages(json);
  if (images.length === 0) {
    return saveImageErrorResult({
      provider,
      model,
      status: 502,
      startTime,
      error: "UC direct image generation returned no images",
      requestBody,
    });
  }

  const created =
    json &&
    typeof json === "object" &&
    typeof (json as Record<string, unknown>).created === "number"
      ? ((json as Record<string, unknown>).created as number)
      : null;

  return saveImageSuccessResult({
    provider,
    model,
    startTime,
    requestBody,
    responseBody: { images_count: images.length },
    created,
    images,
  });
}

export async function handleUcImageGeneration({
  model,
  provider,
  body,
  credentials,
  log,
  signal,
  fetchImpl = fetch,
  sleepImpl = realSleep,
}: UcImageHandlerArgs) {
  const startTime = Date.now();

  const prompt = typeof body.prompt === "string" ? body.prompt.trim() : "";
  if (!prompt) {
    return saveImageErrorResult({
      provider,
      model,
      status: 400,
      startTime,
      error: "Prompt is required for UC image generation",
    });
  }

  if (isUcDirectCredential(credentials)) {
    return handleUcDirectImage({
      model,
      provider,
      body,
      credentials,
      log,
      signal,
      fetchImpl,
      startTime,
      prompt,
    });
  }
  return handleUcPersonaImage({
    model,
    provider,
    body,
    credentials,
    log,
    signal,
    fetchImpl,
    sleepImpl,
    startTime,
    prompt,
  });
}

import { createHash, timingSafeEqual } from "node:crypto";
import { isModelSyncInternalRequest } from "../../../shared/services/modelSyncScheduler";
import { isAuthRequired, isDashboardSessionAuthenticated } from "../../../shared/utils/apiAuth";
import type { AuthOutcome, PolicyContext, RoutePolicy } from "../context";
import { allow, reject } from "../context";
import { extractApiKey, isValidApiKey } from "../../../sse/services/auth";
import { getApiKeyMetadata } from "../../../lib/db/apiKeys";
import { hasManageScope } from "../../../lib/api/requireManagementAuth";
import {
  hasMcpConnectOrManageScope,
  MCP_CONNECT_SCOPE,
} from "../../../shared/constants/managementScopes";
import { evaluateAccessTokenAuth } from "../accessTokenAuth";
import { isInternalServiceRequest } from "../../../lib/api/internalServiceAuth";
import {
  VIDEO_BRIDGE_BROKER_PATH,
  VIDEO_BRIDGE_DRILLDOWN_PATH,
  isVideoBridgeBrokerTokenRequest,
} from "../../../lib/guardrails/videoBridgeBrokerAuth";
import {
  hasValidLoopbackCliToken,
  isLoopbackRequest,
  isPrivateLanRequest,
  LOCAL_CLI_SUBJECT,
} from "../peerContext";
import {
  isAlwaysProtectedPath,
  isLocalOnlyBypassableByManageScope,
  isLocalOnlyPath,
} from "../routeGuard";

const MODEL_SYNC_MANAGEMENT_PATH = /^\/api\/providers\/[^/]+\/(sync-models|models)$/;

function hasBearerToken(headers: Headers): boolean {
  const authHeader = headers.get("authorization") ?? headers.get("Authorization");
  return typeof authHeader === "string" && authHeader.trim().toLowerCase().startsWith("bearer ");
}

function isInternalModelSyncRequest(ctx: PolicyContext): boolean {
  if (!MODEL_SYNC_MANAGEMENT_PATH.test(ctx.classification.normalizedPath)) return false;
  return isModelSyncInternalRequest(ctx.request);
}

const WS_BRIDGE_INTERNAL_PATH = "/api/internal/codex-responses-ws";
const WS_BRIDGE_SECRET_HEADER = "x-omniroute-ws-bridge-secret";

// The in-process codex Responses-over-WebSocket proxy authenticates its internal
// authenticate/prepare calls with a per-process, unguessable secret minted by
// server-ws.mjs (OMNIROUTE_WS_BRIDGE_SECRET). Without this carve-out the MANAGEMENT
// classification 401s that loopback call, which then leaks chunked/security headers
// back onto the upgrade socket. The internal route re-validates the secret timing-safe
// (bridgeSecretMatches), so this is the same trust boundary, surfaced one layer up.
function isValidWsBridgeRequest(ctx: PolicyContext): boolean {
  if (ctx.classification.normalizedPath !== WS_BRIDGE_INTERNAL_PATH) return false;
  const expected = process.env.OMNIROUTE_WS_BRIDGE_SECRET || "";
  if (!expected) return false;
  const provided = ctx.request.headers?.get?.(WS_BRIDGE_SECRET_HEADER) ?? "";
  if (!provided) return false;
  const expectedHash = createHash("sha256").update(expected).digest();
  const providedHash = createHash("sha256").update(provided).digest();
  return timingSafeEqual(expectedHash, providedHash);
}

// Loopback-only inspector ingest endpoint (D4). Token-gated in its own route
// handler (INSPECTOR_INTERNAL_INGEST_TOKEN); exempt from management auth so the
// standalone MITM proxy (server.cjs) can post captured traffic without a
// dashboard cookie. See the carve-out in evaluate() below.
const INSPECTOR_INGEST_PATH = "/api/tools/traffic-inspector/internal/ingest";

export const managementPolicy: RoutePolicy = {
  routeClass: "MANAGEMENT",
  async evaluate(ctx: PolicyContext): Promise<AuthOutcome> {
    const path = ctx.classification.normalizedPath;

    // Codex Responses-over-WS bridge: honor the per-process bridge secret before
    // the loopback/auth gates so the proxy's internal calls aren't 401'd (which
    // would corrupt the WS upgrade response). The internal route re-checks it.
    if (isValidWsBridgeRequest(ctx)) {
      return allow({ kind: "management_key", id: "ws-bridge", label: "codex-ws-bridge-secret" });
    }

    // Tier 1: local-only gate — block spawn-capable routes from non-loopback.
    //
    // Carve-out: a small allow-list of LOCAL_ONLY paths (see
    // LOCAL_ONLY_MANAGE_SCOPE_BYPASS_PREFIXES) is reachable from non-loopback
    // when the caller presents EITHER (a) a valid API key with the `manage`
    // scope, or (b) an authenticated dashboard session. This lets:
    //   - headless / remote MCP clients drive the management surface with a
    //     manage-scope Bearer key, and
    //   - the Dashboard UI itself (cookie session) render its MCP pages
    //     (/api/mcp/status, /api/mcp/tools) from a public hostname.
    //
    // The strict-loopback default still applies to everything else (notably
    // the subprocess-spawning /api/cli-tools/runtime/* surface, which is NOT
    // in the bypass list).
    //
    // Anonymous (no Bearer / invalid key / wrong scope / no session) requests
    // still hit the same 403 LOCAL_ONLY they did before.
    if (
      isLocalOnlyPath(path, ctx.request?.method) &&
      !isLoopbackRequest(ctx) &&
      !isPrivateLanRequest(ctx)
    ) {
      if (isLocalOnlyBypassableByManageScope(path)) {
        // Management auth is header-only — a URL-borne token must never satisfy a
        // manage-scope bypass of a LOCAL_ONLY route. See #3300 follow-up.
        const apiKey = [REDACTED] as unknown as Request, { allowUrl: false });
        if (apiKey) {
          try {
            if (await isValidApiKey(apiKey)) {
              const meta = await getApiKeyMetadata(apiKey);
              // #7895: the `/api/mcp/` carve-out ALSO accepts the narrow
              // `mcp:connect` scope, so remote MCP-only callers don't need
              // broad `manage`/`admin` just to reach the transport routes.
              // Scoped to `/api/mcp/` ONLY — every other LOCAL_ONLY bypass
              // prefix still requires full `hasManageScope` (below).
              const scopeGranted =
                path.startsWith("/api/mcp/") && meta
                  ? hasMcpConnectOrManageScope(meta.scopes)
                  : Boolean(meta && hasManageScope(meta.scopes));
              if (meta && scopeGranted) {
                // Distinguish admin vs manage vs the narrow mcp:connect scope in
                // the audit label so log review can tell which privilege
                // actually granted the bypass.
                const grantedBy = meta.scopes.includes("admin")
                  ? "admin"
                  : meta.scopes.includes("manage")
                    ? "manage"
                    : meta.scopes.includes(MCP_CONNECT_SCOPE)
                      ? "mcp-connect"
                      : "manage";
                return allow({
                  kind: "management_key",
                  id: meta.id,
                  label: `api-key-${grantedBy}-scope-local-only-bypass`,
                });
              }
            }
          } catch (err) {
            // Auth backend (DB / file store) failure: surface as 503 so the
            // caller can retry. Anything else (TypeError / ReferenceError /
            // programmer error) is logged so it's not silently swallowed —
            // the policy still degrades closed (503) to avoid leaking the
            // route, but we leave a breadcrumb for ops.
            console.error("[managementPolicy] manage-scope bypass auth check failed", err);
            return reject(503, "AUTH_BACKEND_UNAVAILABLE", "Service temporarily unavailable");
          }
        }
        // Dashboard session bypass: the Dashboard UI itself needs to render
        // /api/mcp/status, /api/mcp/tools, etc. from a public hostname. Cookie
        // auth is already proof of an authenticated admin — same trust level
        // as a manage-scope Bearer for the surface in scope here.
        try {
          if (await isDashboardSessionAuthenticated(ctx.request)) {
            return allow({
              kind: "dashboard_session",
              id: "dashboard",
              label: "dashboard-session-local-only-bypass",
            });
          }
        } catch (err) {
          // Mirror the manage-scope branch above: degrade closed (503) rather
          // than leaking the route through an unhandled 500, but log a
          // breadcrumb for ops. Session-store DB failure / cookie parsing
          // error / JWT decode throw all land here.
          console.error("[managementPolicy] dashboard-session bypass auth check failed", err);
          return reject(503, "AUTH_BACKEND_UNAVAILABLE", "Service temporarily unavailable");
        }
      }
      return reject(403, "LOCAL_ONLY", "This endpoint requires localhost access");
    }

    // Inspector ingest (D4): the standalone MITM proxy (server.cjs) posts
    // captured AgentBridge traffic to this loopback-only endpoint. It carries
    // its own shared-secret token (validated in the route handler), so it does
    // not also need a dashboard session / management key. The LOCAL_ONLY gate
    // above already rejected any non-loopback caller; we additionally require a
    // strict loopback request here so a LAN peer cannot reach it without auth.
    if (path === INSPECTOR_INGEST_PATH && isLoopbackRequest(ctx)) {
      return allow({
        kind: "management_key",
        id: "inspector-ingest",
        label: "inspector-ingest-token",
      });
    }

    if (isInternalModelSyncRequest(ctx)) {
      return allow({ kind: "management_key", id: "model-sync", label: "internal-model-sync" });
    }

    // Exact-path, per-process authenticated self-hops used by the public Video
    // Bridge guardrail and its isolated drill-down lifecycle. The unconditional
    // LOCAL_ONLY gate above has already rejected remote peers; this carve-out is
    // deliberately not valid for runtime status or any future adjacent path.
    if (
      (path === VIDEO_BRIDGE_BROKER_PATH || path === VIDEO_BRIDGE_DRILLDOWN_PATH) &&
      isLoopbackRequest(ctx) &&
      isVideoBridgeBrokerTokenRequest(ctx.request as unknown as Request, path)
    ) {
      const drilldown = path === VIDEO_BRIDGE_DRILLDOWN_PATH;
      return allow({
        kind: "management_key",
        id: drilldown ? "video-bridge-drilldown" : "video-bridge-broker",
        label: drilldown ? "internal-video-bridge-drilldown" : "internal-video-bridge-broker",
      });
    }

    if (isLoopbackRequest(ctx) && isInternalServiceRequest(ctx.request as unknown as Request)) {
      return allow({
        kind: "management_key",
        id: "internal-service",
        label: "internal-service-token",
      });
    }

    if (hasValidLoopbackCliToken(ctx)) {
      return allow({ ...LOCAL_CLI_SUBJECT });
    }

    // MCP path carve-out (#9159): accept mcp:connect, manage, or admin
    // scope for /api/mcp/* from any origin (loopback, private LAN, or remote).
    // Loopback/LAN requests skip the Tier 1 bypass gate above, so with
    // requireLogin=true they would fall through to the generic API-key check
    // which only accepts manage/admin -- rejecting mcp:connect-only keys.
    // This carve-out mirrors the existing Tier 1 MCP check but without the
    // locality guard, so it catches the loopback/LAN requests that the Tier 1
    // gate does not reach.
    if (path.startsWith("/api/mcp/")) {
      const apiKey = [REDACTED] as unknown as Request, { allowUrl: false });
      if (apiKey) {
        try {
          if (await isValidApiKey(apiKey)) {
            const meta = await getApiKeyMetadata(apiKey);
            if (meta && hasMcpConnectOrManageScope(meta.scopes)) {
              const grantedBy = meta.scopes.includes("admin")
                ? "admin"
                : meta.scopes.includes("manage")
                  ? "manage"
                  : "mcp-connect";
              return allow({
                kind: "management_key",
                id: meta.id,
                label: `api-key-${grantedBy}-scope-mcp-carve-out`,
              });
            }
          }
        } catch {
          return reject(503, "AUTH_BACKEND_UNAVAILABLE", "Service temporarily unavailable");
        }
      }
    }

    // Tier 2: always-protected routes skip the requireLogin=false bypass.
    //
    // The fresh-install bootstrap branch inside isAuthRequired() is loopback-only.
    // Hand it the SAME trusted verdict the LOCAL_ONLY gate above used (token-stamped
    // real TCP peer via peerContext) instead of letting it sniff ctx.request — the
    // ORIGINAL request still carries every client-supplied header at this point,
    // and the Host header was how a remote caller reached the anonymous
    // POST /api/settings/require-login write (GHSA-7pq4-8pvv-rx7r).
    if (
      !isAlwaysProtectedPath(path) &&
      !(await isAuthRequired(ctx.request, { loopback: isLoopbackRequest(ctx) }))
    ) {
      return allow({ kind: "anonymous", id: "anonymous", label: "auth-disabled" });
    }

    if (await isDashboardSessionAuthenticated(ctx.request)) {
      return allow({ kind: "dashboard_session", id: "dashboard" });
    }

    // Allow API keys with the `manage` scope — enables headless / programmatic
    // management (e.g. provisioning providers, setting rate limits) without
    // a browser session. The pieces below already exist and are used by
    // `requireManagementAuth` on individual routes; wiring them here closes
    // the gap so management auth is consistent across the policy layer.
    //
    // Error handling mirrors `requireManagementAuth.ts`: a thrown
    // isValidApiKey / getApiKeyMetadata indicates the auth backend is
    // unhealthy, which is a 503, not a 403 — masking it as an auth failure
    // would tell callers their credentials are wrong when the real problem
    // is that the server cannot validate any credential right now.
    // Scoped CLI access token (remote mode). Evaluated BEFORE the API-key branch
    // because `oma_` tokens are management credentials, not inference API keys.
    // Shared with `requireManagementAuth` (no drift). Scope enforced per the
    // method+admin-allowlist policy (inferRequiredScope).
    const accessVerdict = evaluateAccessTokenAuth(ctx.request as unknown as Request);
    switch (accessVerdict.kind) {
      case "ok":
        return allow({
          kind: "management_key",
          id: accessVerdict.id,
          label: `access-token:[REDACTED]}`,
        });
      case "error":
        return reject(503, "AUTH_BACKEND_UNAVAILABLE", "Service temporarily unavailable");
      case "invalid":
        return reject(401, "AUTH_001", "Invalid or expired access token");
      case "insufficient":
        return reject(
          403,
          "AUTH_SCOPE",
          `Access token scope '${accessVerdict.have}' is insufficient; '${accessVerdict.need}' required.`
        );
      case "absent":
        break; // no oma_ token → fall through to API-key auth
    }

    // Management auth is header-only — a URL-borne token must not authenticate
    // a management route. See #3300 follow-up.
    const apiKey = [REDACTED] as unknown as Request, { allowUrl: false });
    if (apiKey) {
      try {
        if (await isValidApiKey(apiKey)) {
          const meta = await getApiKeyMetadata(apiKey);
          // getApiKeyMetadata returns null whenever the row has no id,
          // so when `meta` is truthy `meta.id` is guaranteed non-empty.
          if (meta && hasManageScope(meta.scopes)) {
            return allow({
              kind: "management_key",
              id: meta.id,
              label: "api-key-manage-scope",
            });
          }
        }
      } catch {
        return reject(503, "AUTH_BACKEND_UNAVAILABLE", "Service temporarily unavailable");
      }
    }

    const bearerPresent = hasBearerToken(ctx.request.headers);
    return reject(
      bearerPresent ? 403 : 401,
      "AUTH_001",
      bearerPresent ? "Invalid management token" : "[REDACTED] required"
    );
  },
};

import type { AuthOutcome, PolicyContext, RoutePolicy } from "../context";
import { allow } from "../context";
import { hasValidLoopbackCliToken, LOCAL_CLI_SUBJECT } from "../peerContext";

export const publicPolicy: RoutePolicy = {
  routeClass: "PUBLIC",
  async evaluate(ctx: PolicyContext): Promise<AuthOutcome> {
    // PUBLIC never rejects — but the SUBJECT still matters. `runAuthzPipeline`
    // strips CLI_TOKEN_HEADER from the forwarded headers for every route class,
    // so a handler can only learn that a local CLI authenticated from the stamp
    // this policy produces. Some PUBLIC-classified routes intentionally serve a
    // reduced anonymous view and the full one to a management principal (GET
    // /api/monitoring/health, GHSA-mvf8-qc78-5mxm): without this branch the
    // loopback CLI holding a valid machine token was permanently downgraded to
    // the anonymous view: the health payload lost `version`, which is what the
    // check:pack-boot release gate asserts on the packed tarball. Regression
    // introduced by #11040 (GHSA-mvf8-qc78-5mxm hardening).
    // The verdict is strictly loopback + constant-time token comparison, the
    // same gate the MANAGEMENT policy applies.
    if (hasValidLoopbackCliToken(ctx)) {
      return allow({ ...LOCAL_CLI_SUBJECT });
    }
    return allow({ kind: "anonymous", id: "anonymous" });
  },
};
